-- A FIXTURE tree shaped like QuickJS (cartograph.qjs): JSValue a 16-byte struct {u, tag} passed BY VALUE, the JS_TAG_
-- enum (and a LARGER decoy BC_TAG_ enum the units barely use), JSCFunction's `int argc, JSValue *argv` with the call
-- path's undefined PADDING, JS_Throw's store-and-return sentinel and throwers through a call and a local, the JS_Is<X>
-- predicates, typeof's default arm, JS_CFUNC_DEF / JS_CFUNC_MAGIC_DEF tables. Shared by qjs_spec and
-- cinterp_adapter_spec: dofile it for FILES.
local FILES = {
    ['quickjs.h'] = table.concat({
        '#ifndef QUICKJS_H', '#define QUICKJS_H', '#include <stdbool.h>', '#include <stdint.h>', '#include <stdarg.h>',
        'typedef struct JSContext JSContext;',
        'enum {',
        '    JS_TAG_FIRST = -2, JS_TAG_SYMBOL = -2, JS_TAG_OBJECT = -1, JS_TAG_INT = 0, JS_TAG_BOOL = 1, JS_TAG_NULL = 2,',
        '    JS_TAG_UNDEFINED = 3, JS_TAG_EXCEPTION = 6, JS_TAG_FLOAT64 = 8,',
        '};',
        'typedef union JSValueUnion { int32_t int32; double float64; void *ptr; } JSValueUnion;',
        'typedef struct JSValue { JSValueUnion u; int64_t tag; } JSValue;',
        '#define JSValueConst JSValue',
        '#define JS_VALUE_GET_TAG(v) ((int32_t)(v).tag)',
        '#define JS_MKVAL(tag, val) (JSValue){ (JSValueUnion){ .int32 = val }, tag }',
        '#define JS_NULL JS_MKVAL(JS_TAG_NULL, 0)', '#define JS_UNDEFINED JS_MKVAL(JS_TAG_UNDEFINED, 0)',
        '#define JS_FALSE JS_MKVAL(JS_TAG_BOOL, 0)', '#define JS_TRUE JS_MKVAL(JS_TAG_BOOL, 1)',
        '#define JS_EXCEPTION JS_MKVAL(JS_TAG_EXCEPTION, 0)',
        'static inline bool JS_IsNumber(JSValueConst v) { int tag = JS_VALUE_GET_TAG(v); return tag == JS_TAG_INT || tag == JS_TAG_FLOAT64; }',
        'static inline bool JS_IsBool(JSValueConst v) { return JS_VALUE_GET_TAG(v) == JS_TAG_BOOL; }',
        'static inline bool JS_IsNull(JSValueConst v) { return JS_VALUE_GET_TAG(v) == JS_TAG_NULL; }',
        'static inline bool JS_IsUndefined(JSValueConst v) { return JS_VALUE_GET_TAG(v) == JS_TAG_UNDEFINED; }',
        'static inline bool JS_IsException(JSValueConst v) { return JS_VALUE_GET_TAG(v) == JS_TAG_EXCEPTION; }',
        'static inline bool JS_IsSymbol(JSValueConst v) { return JS_VALUE_GET_TAG(v) == JS_TAG_SYMBOL; }',
        'static inline bool JS_IsObject(JSValueConst v) { return JS_VALUE_GET_TAG(v) == JS_TAG_OBJECT; }',
        'static inline JSValue js_bool(bool v) { return JS_MKVAL(JS_TAG_BOOL, v); }',
        'typedef JSValue JSCFunction(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv);',
        'typedef JSValue JSCFunctionMagic(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv, int magic);',
        'typedef struct JSCFunctionListEntry { const char *name; int length; void *func; int magic; } JSCFunctionListEntry;',
        '#define JS_CFUNC_DEF(name, length, func1) { name, length, (void *)func1, 0 }',
        '#define JS_CFUNC_MAGIC_DEF(name, length, func1, magic) { name, length, (void *)func1, magic }',
        'JSValue JS_Throw(JSContext *ctx, JSValue obj);',
        'JSValue JS_ThrowTypeError(JSContext *ctx, const char *fmt, ...);',
        '#endif',
    }, '\n') .. '\n',
    ['quickjs.c'] = table.concat({
        '#include "quickjs.h"',
        '/* the serializer\'s tags: MORE constants than JS_TAG_, named once */',
        'enum { BC_TAG_NULL = 1, BC_TAG_UNDEFINED, BC_TAG_BOOL_FALSE, BC_TAG_BOOL_TRUE, BC_TAG_INT32, BC_TAG_FLOAT64, BC_TAG_STRING,',
        '       BC_TAG_OBJECT, BC_TAG_ARRAY, BC_TAG_BIG_INT, BC_TAG_TEMPLATE };',
        'int bc_first(void) { return BC_TAG_NULL; }',
        'struct JSContext { JSValue current_exception; int depth; };',
        'JSValue JS_Throw(JSContext *ctx, JSValue obj)',
        '{',
        '    ctx->current_exception = obj;',
        '    return JS_EXCEPTION;',
        '}',
        'JSValue JS_ThrowTypeError(JSContext *ctx, const char *fmt, ...)',
        '{',
        '    JSValue val;',
        '    va_list ap;',
        '    va_start(ap, fmt);',
        '    val = JS_Throw(ctx, JS_NULL);',
        '    va_end(ap);',
        '    return val;',
        '}',
        'static JSValue JS_ThrowTypeErrorNotAnObject(JSContext *ctx)',
        '{',
        '    return JS_ThrowTypeError(ctx, "not an object");',
        '}',
        'static int js_operator_typeof(JSContext *ctx, JSValue op1)',
        '{',
        '    int atom;',
        '    switch (JS_VALUE_GET_TAG(op1)) {',
        '    case JS_TAG_INT: case JS_TAG_FLOAT64: atom = 1; break;',
        '    case JS_TAG_UNDEFINED: atom = 2; break;',
        '    case JS_TAG_BOOL: atom = 3; break;',
        '    case JS_TAG_NULL: case JS_TAG_OBJECT: atom = 4; break;',
        '    case JS_TAG_SYMBOL: atom = 5; break;',
        '    default: atom = 99; break;',
        '    }',
        '    return atom;',
        '}',
        '/* the call path: the argument array PADDED with undefined up to the registered length */',
        'JSValue js_call_c_function(JSContext *ctx, JSCFunction *f, int length, int argc, JSValueConst *argv, JSValue *arg_buf)',
        '{',
        '    int i;',
        '    for (i = 0; i < argc; i++)',
        '        arg_buf[i] = argv[i];',
        '    for (i = argc; i < length; i++)',
        '        arg_buf[i] = JS_UNDEFINED;',
        '    return f(ctx, JS_UNDEFINED, argc, arg_buf);',
        '}',
        'static JSValue js_symbol_keyFor(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)',
        '{',
        '    if (!JS_IsSymbol(argv[0]))',
        '        return JS_ThrowTypeError(ctx, "not a symbol");',
        '    return JS_UNDEFINED;',
        '}',
        'static JSValue js_object_getPrototypeOf(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv, int magic)',
        '{',
        '    JSValueConst val = argv[0];',
        '    if (JS_VALUE_GET_TAG(val) != JS_TAG_OBJECT) {',
        '        if (magic || JS_VALUE_GET_TAG(val) == JS_TAG_NULL || JS_VALUE_GET_TAG(val) == JS_TAG_UNDEFINED)',
        '            return JS_ThrowTypeErrorNotAnObject(ctx);',
        '    }',
        '    return JS_NULL;',
        '}',
        'static JSValue js_array_isArray(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)',
        '{',
        '    return js_bool(JS_IsObject(argv[0]));',
        '}',
        '/* reads its COUNT: an absent argument is not the undefined the array is padded with */',
        'static JSValue js_global_needsArg(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)',
        '{',
        '    if (argc < 1)',
        '        return JS_ThrowTypeError(ctx, "an argument is required");',
        '    return argv[0];',
        '}',
        '/* a callee that ALONE spends a small budget: made an unknown call, the run within it again */',
        'static int slow_helper(JSContext *ctx)',
        '{',
        '    ' .. string.rep('ctx->depth++; ', 60),
        '    return ctx->depth;',
        '}',
        'static JSValue js_global_slow(JSContext *ctx, JSValueConst this_val, int argc, JSValueConst *argv)',
        '{',
        '    slow_helper(ctx);',
        '    if (!JS_IsSymbol(argv[0]))',
        '        return JS_ThrowTypeError(ctx, "not a symbol");',
        '    return JS_UNDEFINED;',
        '}',
        'static const JSCFunctionListEntry js_object_funcs[] = {',
        '    JS_CFUNC_MAGIC_DEF("getPrototypeOf", 1, js_object_getPrototypeOf, 0 ),',
        '};',
        'static const JSCFunctionListEntry js_reflect_funcs[] = {',
        '    JS_CFUNC_MAGIC_DEF("getPrototypeOf", 1, js_object_getPrototypeOf, 1 ),',
        '};',
        'static const JSCFunctionListEntry js_symbol_funcs[] = {',
        '    JS_CFUNC_DEF("keyFor", 1, js_symbol_keyFor ),',
        '};',
        'static const JSCFunctionListEntry js_array_funcs[] = {',
        '    JS_CFUNC_DEF("isArray", 1, js_array_isArray ),',
        '};',
        'static const JSCFunctionListEntry js_global_funcs[] = {',
        '    JS_CFUNC_DEF("needsArg", 1, js_global_needsArg ),',
        '    JS_CFUNC_DEF("slow", 1, js_global_slow ),',
        '};',
        'const void *js_tables[] = { js_object_funcs, js_reflect_funcs, js_symbol_funcs, js_array_funcs, js_global_funcs };',
    }, '\n') .. '\n',
}
return FILES
